const tabId = 1854033397;
const filterDetails = await browserjs(tabId, () => {
  const allLabels = Array.from(document.querySelectorAll('label, button, input'));
  const relevant = [];
  for (const el of allLabels) {
    const text = el.textContent?.trim().replace(/\s+/g, ' ') || '';
    if (
      text.includes('55"') ||
      text.includes('Price') ||
      text.includes('Anti-Reflection') ||
      text.includes('Anti-Reflective') ||
      text.includes('Diagonal Screen Size') ||
      text.includes('$') ||
      text.includes('Rating') ||
      text.includes('Sort')
    ) {
      relevant.push({
        tagName: el.tagName,
        type: el.getAttribute('type'),
        id: el.id,
        name: el.getAttribute('name'),
        className: el.className,
        text: text.slice(0, 80),
        checked: el.checked,
        ariaChecked: el.getAttribute('aria-checked'),
        ariaExpanded: el.getAttribute('aria-expanded')
      });
    }
  }
  return relevant;
});
console.log(JSON.stringify(filterDetails, null, 2));

