// Let's see the current sort value and extract the reviews on S85H
const s85hReviews = await browserjs(tabId, () => {
  const sortVal = document.querySelector('.FilterSortBar_sortValue__UgMOX')?.innerText?.trim();
  const reviewCards = Array.from(document.querySelectorAll('[class*="ReviewCard"], [class*="reviewCard"], [class*="ReviewItem"], [class*="reviewItem"], [class*="review-item"], [data-testid*="review"]'));

  // If specific class not found, let's find review elements
  const fallbackCards = Array.from(document.querySelectorAll('[class*="review"]')).filter(el => {
    return el.querySelector('[class*="rating"], [class*="star"], [class*="title"]') && el.innerText.length > 50;
  });

  const cards = reviewCards.length > 0 ? reviewCards : fallbackCards;

  return {
    sortVal,
    cardsCount: cards.length,
    reviews: cards.slice(0, 10).map(c => {
      const author = c.querySelector('[class*="author"], [class*="name"], [class*="user"]')?.innerText?.trim();
      const date = c.querySelector('[class*="date"], [class*="time"]')?.innerText?.trim();
      const title = c.querySelector('[class*="title"], [class*="heading"], h3, h4, h5')?.innerText?.trim();
      const text = c.querySelector('[class*="body"], [class*="content"], [class*="text"], [class*="comment"], p')?.innerText?.trim();
      const helpful = c.querySelector('[class*="helpful"], [class*="vote"], [class*="like"]')?.innerText?.trim();
      const rating = c.querySelector('[class*="rating"], [class*="star"], [aria-label*="star"], [aria-label*="rating"]')?.getAttribute('aria-label') || c.querySelector('[class*="rating"]')?.innerText?.trim();
      return {
        author,
        date,
        title,
        text,
        helpful,
        rating,
        rawSnippet: c.innerText.slice(0, 300)
      };
    })
  };
});
console.log(JSON.stringify(s85hReviews, null, 2));
"}

