const res = await browserjs(tabId, () => {
  const btn = document.querySelector('.FilterSortBar_sortBtn__DVmHs');
  let dropdown = document.querySelector('.FilterSortBar_dropdown__dN9iq');
  if (!dropdown && btn) {
    btn.click();
    dropdown = document.querySelector('.FilterSortBar_dropdown__dN9iq');
  }
  if (!dropdown) return "Dropdown not found";

  const options = Array.from(dropdown.querySelectorAll('li, button, div, span')).filter(el => el.innerText?.trim() === 'Most helpful');
  if (options.length > 0) {
    options[0].click();
    return { clicked: true, text: options[0].innerText };
  }
  return { clicked: false, dropdownHtml: dropdown.innerHTML };
});
console.log(res);

